  {value:"profile",label:"Profile",icon:"user"}, {value:"side-panel",label:"Panel",icon:"panel-left"},
  {value:"dock",label:"Dock",icon:"layout-grid"}, {value:"chat",label:"Chat",icon:"message-circle"},
